import {traits,band} from './model.mjs';
import {thinkingViews} from './thinking-views.mjs';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const discoveryIntents=['self','relationships','blindspots','pressure','growth'];
export function validIntent(value){return discoveryIntents.includes(value)?value:'self'}
export function intentContext(value){return value==='relationships'?'relationships':value==='pressure'?'pressure':'daily'}
export function intentDimensions(value){return ({self:[0,1,2],relationships:[0,3,4],blindspots:[3,1,0],pressure:[4,2,0],growth:[2,3,1]})[validIntent(value)]}
export function intentOptions(language='en'){return language==='hi'?[
 {key:'self',icon:'◉',title:'खुद को बेहतर समझना है',question:'मैं ऐसे क्यों सोचता और जवाब देता हूँ?',description:'अपनी पसंद, खूबियों और ज़रूरतों को नाम दें।'},
 {key:'relationships',icon:'♡',title:'रिश्तों में बेहतर जुड़ना है',question:'बार-बार वही गलतफ़हमी क्यों होती है?',description:'बातचीत और फैसलों की अलग पसंद समझें।'},
 {key:'blindspots',icon:'✧',title:'कुछ छूट तो नहीं रहा?',question:'मेरी अच्छी नीयत का असर अलग क्यों होता है?',description:'अपने ढर्रे को एक नए नज़रिए से देखें।'},
 {key:'pressure',icon:'≈',title:'दबाव में खुद को समझना है',question:'मुश्किल परिस्थिति में मेरी गति क्यों बदलती है?',description:'देखें किस तरह का सहारा आपके लिए मददगार हो सकता है।'},
 {key:'growth',icon:'↗',title:'अपना अगला कदम खोजना है',question:'मैं कहाँ से सुधार की शुरुआत करूँ?',description:'छोटी, व्यावहारिक activities से शुरुआत करें।'}
 ]:[
 {key:'self',icon:'◉',title:'Understand myself',question:'Why do I think and respond this way?',description:'Put words to your preferences, strengths and needs.'},
 {key:'relationships',icon:'♡',title:'Connect better in relationships',question:'Why do we keep misunderstanding each other?',description:'Explore differences in communication and decisions.'},
 {key:'blindspots',icon:'✧',title:'Notice what I might miss',question:'Why do good intentions sometimes land differently?',description:'Look at familiar patterns from a new angle.'},
 {key:'pressure',icon:'≈',title:'Understand myself under pressure',question:'Why does my pace change when things get difficult?',description:'Explore what might help you feel supported.'},
 {key:'growth',icon:'↗',title:'Find my next step',question:'Where could I begin to improve?',description:'Turn a little self-understanding into a practical activity.'}
 ]}
export function discoveryHomeMarkup({language='en',draft=null,reportLanguageNote='',reportLanguageDir='ltr',demoView='map'}){
 const hi=language==='hi',done=draft?.answers.filter(a=>a!==null).length||0;return `<section class="purpose-hero" data-no-translate><div class="purpose-copy"><p class="eyebrow">${hi?'खुद को समझने की एक छोटी शुरुआत':'A LITTLE SELF-UNDERSTANDING GOES A LONG WAY'}</p><h1>${hi?'खुद को समझें।<br><span>थोड़ा बेहतर जुड़ें।</span>':'Understand yourself.<br><span>Connect a little better.</span>'}</h1><p class="purpose-lead">${hi?'अपनी पसंद, रिश्तों और फैसलों को नए नज़रिए से देखें। आसान जानकारी, इंटरैक्टिव ग्राफ़ और एक छोटा अगला कदम पाएँ।':'See how you think, connect and make decisions. Get personal insights, interactive views and one small step to try.'}</p><div class="purpose-facts"><span>36 ${hi?'सवाल':'questions'}</span><span>${hi?'लगभग 6–9 मिनट':'About 6–9 minutes'}</span><span>${hi?'पूरी रिपोर्ट अभी मुफ़्त':'Full report free for now'}</span></div>${draft?`<p class="purpose-resume">${hi?`36 में से ${done} जवाब सेव हैं। जहाँ छोड़ा था, वहीं से आगे बढ़ें।`:`${done} of 36 answers saved. Pick up where you left off.`}</p>`:''}<div class="purpose-cta-row"><button class="primary" data-action="${draft?'resume':'start'}">${hi?(draft?'टेस्ट जारी रखें':'टेस्ट शुरू करें'):(draft?'Continue my test':'Start my test')} <span aria-hidden="true">→</span></button><button class="text-button" id="explore-preview">${hi?'रिपोर्ट की झलक देखें ↓':'Explore a report preview ↓'}</button></div><p class="purpose-reassurance">${hi?'कोई account या email ज़रूरी नहीं। अपनी गति से जवाब दें।':'No account or email needed. Answer at your own pace.'}</p>${draft?`<button class="text-button purpose-restart" data-action="new">${hi?'फिर से शुरू करें':'Start again'}</button>`:''}<p class="purpose-language-note" lang="${language}" dir="${reportLanguageDir}">${esc(reportLanguageNote)}</p></div><section class="home-demo" id="home-report-preview" aria-label="${hi?'उदाहरण रिपोर्ट की झलक':'Example report preview'}"><div class="home-demo-heading"><span class="demo-brand">✳ innerly.</span><span class="example-badge">${hi?'उदाहरण · आपके नतीजे नहीं':'EXAMPLE · NOT YOUR RESULTS'}</span></div><div class="home-demo-tabs" role="group" aria-label="${hi?'रिपोर्ट का एक नज़रिया चुनें':'Explore an example view'}">${thinkingViews(language).map(view=>`<button data-home-view="${view.key}" aria-pressed="${view.key===demoView}"><span aria-hidden="true">${view.icon}</span>${({map:hi?'पूरी तस्वीर':'Landscape',bar:hi?'सहज पसंद':'Preferences',pie:hi?'पसंद का मेल':'Connections',line:hi?'आपकी यात्रा':'Journey'})[view.key]}</button>`).join('')}</div><div id="home-demo-content">${homeDemoMarkup(demoView,language)}</div><p class="home-demo-note">${hi?'उदाहरण scores केवल feature दिखाने के लिए हैं। आपके results आपके अपने 36 जवाबों से बनेंगे।':'Illustrative scores show how the report works. Your results will come from your own 36 answers.'}</p></section></section><section class="start-reasons" data-no-translate><div class="home-section-heading"><p class="eyebrow">${hi?'आपकी अपनी वजह':'YOUR OWN REASON TO BEGIN'}</p><h2>${hi?'आज आप क्या समझना चाहते हैं?':'What brings you here today?'}</h2><p>${hi?'किसी एक से शुरू करें, या सीधे test भरें। सभी रास्ते उसी 36-सवाल reflection की ओर जाते हैं।':'Start with what feels relevant, or jump straight into the test. Each starting point uses the same 36-question reflection.'}</p></div><div class="reason-grid">${intentOptions(language).map(item=>`<button data-start-intent="${item.key}" class="reason-card"><span class="reason-icon" aria-hidden="true">${item.icon}</span><h3>${item.title}</h3><p class="reason-question">${item.question}</p><p>${item.description}</p><span class="reason-go">${hi?(draft?'जारी रखें':'शुरू करें'):(draft?'Continue':'Start here')} <span aria-hidden="true">→</span></span></button>`).join('')}</div></section><section class="home-give" data-no-translate><div class="home-section-heading"><p class="eyebrow">${hi?'टेस्ट के बाद क्या मिलेगा':'WHAT YOU WILL TAKE AWAY'}</p><h2>${hi?'सिर्फ़ एक label नहीं—अपने लिए कुछ उपयोगी।':'Something useful to take into your day.'}</h2></div><div class="give-grid"><article><span>01</span><h3>${hi?'आपकी पसंद की साफ़ तस्वीर':'A clearer picture of your preferences'}</h3><p>${hi?'पाँच dimensions, हर score का आसान मतलब और आपके असली answers का breakdown।':'Five dimensions, plain-language score explanations and a breakdown of your actual answers.'}</p></article><article><span>02</span><h3>${hi?'आपकी रोज़मर्रा की ज़िंदगी से जुड़ी insights':'Insights you can connect to real life'}</h3><p>${hi?'रोज़मर्रा, रिश्तों और दबाव की situations के अलग संदर्भ। चुनें कि क्या आपके अनुभव से मेल खाता है।':'Everyday life, relationships and pressure—explore different contexts, then tell us what resonates with you.'}</p></article><article><span>03</span><h3>${hi?'अपनी गति से एक छोटा कदम':'One small step, at your pace'}</h3><p>${hi?'अपनी activity plan बनाएँ, पूरी report PDF में सेव करें और अपने saved snapshots दोबारा देखें।':'Build a simple activity plan, save your full report as a PDF and revisit your own saved snapshots.'}</p></article></div></section><section class="relationship-prompt" data-no-translate><div><p class="eyebrow">${hi?'जब एक-दूसरे को समझना मुश्किल लगे':'WHEN UNDERSTANDING EACH OTHER FEELS HARD'}</p><h2>${hi?'एक ही बातचीत।<br>दो अलग ज़रूरतें।':'The same conversation.<br>Two different needs.'}</h2><p>${hi?'कोई तुरंत हल चाहता है; किसी को पहले सुना जाना ज़रूरी लगता है। आपकी पसंद इनमें एक factor हो सकती है। Reflection से ऐसे फर्क पर बात करने की शुरुआत मिल सकती है।':'One person may reach for a solution; another may want to feel heard first. Preferences can be one factor in that mismatch. A reflection can give you a starting point for a better conversation.'}</p><button class="primary" data-start-intent="relationships">${hi?'रिश्तों से शुरुआत करें':'Start with relationships'} <span aria-hidden="true">→</span></button></div><div class="conversation-example"><span>${hi?'एक उदाहरण':'AN EXAMPLE'}</span><blockquote>“${hi?'पहले हल निकाल लेते हैं।':'Let’s find a solution.'}”</blockquote><blockquote>“${hi?'मुझे अभी बस सुन लो।':'Could you hear me out first?'}”</blockquote><p>${hi?'किसी रिश्ते के पूरे कारण एक व्यक्ति के test से तय नहीं हो सकते।':'One person’s answers cannot explain an entire relationship.'}</p></div></section><section class="home-faq" data-no-translate><h2>${hi?'शुरू करने से पहले':'Before you begin'}</h2><details><summary>${hi?'क्या यह बताएगा कि मेरा रिश्ता क्यों खराब है?':'Will this tell me why my relationship is struggling?'}</summary><p>${hi?'यह communication और फैसलों की पसंद में possible differences पर सोचने में मदद कर सकता है। किसी रिश्ते में कई factors होते हैं; यह test किसी एक कारण, partner की personality या compatibility का फैसला नहीं करता।':'It can help you reflect on possible differences in communication and decision preferences. Relationships have many influences; this test does not determine a single cause, your partner’s personality or your compatibility.'}</p></details><details><summary>${hi?'क्या मैं बीच में रुक सकता हूँ?':'Can I pause and come back?'}</summary><p>${hi?'हाँ। जवाब इस browser में सेव होते हैं। पाँच सवालों का group पूरा होते ही अगला group खुलता है। Previous या सवालों की सूची से पुराने जवाब बदल सकते हैं।':'Yes. Your answers are saved in this browser. Complete a group of five and the next group opens automatically. You can revisit answers using Previous or the question list.'}</p></details><details><summary>${hi?'क्या रिपोर्ट के लिए भुगतान या email चाहिए?':'Do I need to pay or share my email?'}</summary><p>${hi?'अभी summary और पूरी report मुफ़्त हैं। Email वैकल्पिक है और केवल आपके email app में draft खोलता है। यह खुद को समझने का अभ्यास है; clinically validated assessment नहीं।':'Your summary and full report are free for now. Email is optional and only opens a draft in your own email app. This is a self-reflection exercise, not a clinically validated assessment.'}</p></details></section><section class="home-final-cta" data-no-translate><h2>${hi?'खुद को जानने की शुरुआत यहीं से।':'A little closer to yourself starts here.'}</h2><p>${hi?'36 सवाल। आपकी गति। आपके अपने लिए कुछ insights।':'36 questions. Your pace. Something to reflect on.'}</p><button class="primary" data-action="${draft?'resume':'start'}">${hi?(draft?'टेस्ट जारी रखें':'टेस्ट शुरू करें'):(draft?'Continue my test':'Start my test')} <span aria-hidden="true">→</span></button></section>`;
}
export function homeDemoMarkup(key,language='en'){
 const hi=language==='hi',view=thinkingViews(language).find(v=>v.key===key)||thinkingViews(language)[0],scores=[32,76,68,43,61];let visual='';
 if(view.key==='map'){const point=(i,n)=>[180+Math.cos(-Math.PI/2+i*Math.PI*2/5)*80*n,113+Math.sin(-Math.PI/2+i*Math.PI*2/5)*80*n];visual=`<svg viewBox="0 0 360 230" role="img" aria-label="${hi?'उदाहरण preference landscape':'Example preference landscape'}">${[.25,.5,.75,1].map(n=>`<polygon points="${scores.map((_,i)=>point(i,n).join(',')).join(' ')}" fill="none" stroke="#dce4f3"/>`).join('')}<polygon points="${scores.map((n,i)=>point(i,n/100).join(',')).join(' ')}" fill="#7e98d444" stroke="#6c88c3" stroke-width="2"/>${traits.map((t,i)=>{const p=point(i,scores[i]/100),label=point(i,1.28);return `<circle cx="${p[0]}" cy="${p[1]}" r="5" fill="${t.color}"/><text x="${label[0]}" y="${label[1]}" font-size="11" text-anchor="middle" dominant-baseline="middle" fill="#61718e">${esc(t.short)}</text>`}).join('')}</svg>`}
 if(view.key==='bar')visual=`<div class="home-sample-paths">${traits.map((t,i)=>`<div><p><span>${esc(t.name)}</span><strong>${scores[i]}</strong></p><div><span style="left:${scores[i]}%;background:${t.color}"></span></div></div>`).join('')}</div>`;
 if(view.key==='pie')visual=`<div class="home-sample-connection"><svg viewBox="0 0 330 220" role="img" aria-label="${hi?'दो scores के मेल का उदाहरण':'Example pairing of two scores'}"><rect x="75" y="20" width="180" height="180" rx="12" fill="#f0f4fc"/>${[0,50,100].map(n=>`<path d="M${75+n*1.8} 20v180M75 ${200-n*1.8}h180" stroke="#d4dfee" stroke-dasharray="4 4"/>`).join('')}<path d="M75 77.6h57.6V200" fill="none" stroke="#8fa5cc" stroke-dasharray="4 4"/><circle cx="132.6" cy="77.6" r="17" fill="#617fc324"/><circle cx="132.6" cy="77.6" r="7" fill="#617fc3" stroke="white" stroke-width="3"/></svg><p>${esc(traits[0].name)} <strong>32</strong> · ${esc(traits[2].name)} <strong>68</strong></p></div>`;
 if(view.key==='line')visual=`<div class="home-sample-journey"><svg viewBox="0 0 360 220" role="img" aria-label="${hi?'तीन saved reflections की यात्रा का उदाहरण':'Illustration of three saved reflection snapshots'}"><path d="M25 50H335M25 110H335M25 170H335" stroke="#dce4f1" stroke-dasharray="4 4"/><path d="M45 135L180 94 315 112" fill="none" stroke="#8ba2d0" stroke-width="3"/>${[[45,135],[180,94],[315,112]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="8" fill="#647fc0" stroke="#fff" stroke-width="3"/><text x="${x}" y="202" text-anchor="middle" font-size="12" fill="#61718e">${hi?'झलक':'Snapshot'} ${i+1}</text>`).join('')}</svg></div>`;
 return `<div class="home-sample-view" data-no-translate><h2>${view.title}</h2><p>${view.prompt}</p><div class="home-sample-visual">${visual}</div><div class="home-example-insight"><span aria-hidden="true">✧</span><p>${({map:hi?'आपकी पसंद की पूरी झलक—हर point के पीछे एक कहानी।':'Your whole pattern, with a story behind every point.',bar:hi?'हर score के दोनों सिरे समझें; कम या ज़्यादा होना बेहतर नहीं है।':'Read both ends of each score. A lower or higher position is not better.',pie:hi?'अलग पसंद एक साथ हो सकती हैं। अपने लिए कोई भी दो आयाम चुनें।':'Different preferences can coexist. Explore any two dimensions together.',line:hi?'उदाहरण में तीन झलक हैं। आपकी यात्रा में केवल आपके असली saved tests आएँगे।':'This example shows three snapshots. Your own journey uses only your actual saved assessments.'})[view.key]}</p></div></div>`;
}
export function intentReportMarkup(report,language='en'){if(!discoveryIntents.includes(report.intent))return '';const hi=language==='hi',intent=intentOptions(language).find(i=>i.key===report.intent);return `<section class="report-intent-focus report-panel" data-no-translate><p class="eyebrow">${hi?'आपकी शुरुआत की वजह':'WHAT BROUGHT YOU HERE'}</p><h2>${intent.title}</h2><p>${report.intent==='relationships'?(hi?'इन तीन पहलुओं से शुरुआत करें। ये अलग ज़रूरतों या गलतफ़हमी पर सोचने के possible संकेत हैं; किसी रिश्ते का पक्का कारण या partner का assessment नहीं।':'Start with these three dimensions. They can offer possible conversation starters about different needs or misunderstandings; they do not identify a relationship’s cause or assess your partner.'):(hi?'अपनी वजह को ध्यान में रखते हुए इन पहलुओं को explore करें। आपकी चुनी वजह scores नहीं बदलती।':'Explore these dimensions with your own question in mind. Your starting point does not change your scores.')}</p><div>${intentDimensions(report.intent).map(i=>`<button data-category="${i}"><span>${esc(traits[i].name)} · ${report.scores[i]} / 100</span><strong>${esc(traits[i].profiles[band(report.scores[i])].title)}</strong><span aria-hidden="true">→</span></button>`).join('')}</div></section>`}
